import { ChangeDetectionStrategy, Component, Inject, OnInit, PLATFORM_ID, effect, signal } from '@angular/core';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../core/services/translation.service';
import { PrivacyPolicyContent, PrivacyPolicyService } from '../../core/services/privacy-policy.service';

@Component({
  selector: 'app-privacy-policy',
  standalone: true,
  imports: [CommonModule, TranslateModule],
  templateUrl: './privacy-policy.component.html',
  styleUrl: './privacy-policy.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PrivacyPolicyComponent implements OnInit {
  // null = fall back to the static template below (API unavailable, or no
  // active record published yet for this locale).
  policy = signal<PrivacyPolicyContent | null>(null);

  constructor(
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId: Object,
    public translationService: TranslationService,
    private privacyPolicyService: PrivacyPolicyService,
  ) {
    effect(() => {
      const locale = this.translationService.currentLang() === 'ar' ? 'ar' : 'en';
      this.privacyPolicyService.getPrivacyPolicy(locale).subscribe((result) => this.policy.set(result));
    });
  }

  ngOnInit(): void {
    this.addSchema();
    this.addBreadcrumbSchema();
    if (!isPlatformBrowser(this.platformId)) return;
    setTimeout(() => {
      window.scroll({
        top: 0,
        left: 0,
        behavior: 'smooth'
      });
    }, 500);
  }

  addSchema() {
    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "privacy-policy-webpage-schema";
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "WebPage",
      "name": "Privacy Policy",
      "description": "We respect your right to privacy. Read our policy.",
      "url": "https://www.pixtar.ae/privacy-policy"
    });

    this.document.head.appendChild(script);
  }

  private addBreadcrumbSchema(): void {
    const existingScript = this.document.getElementById("breadcrumb-schema-privacy-policy");
    if (existingScript) {
      return;
    }

    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "breadcrumb-schema-privacy-policy";

    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://www.pixtar.ae/"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "Privacy Policy",
          "item": "https://www.pixtar.ae/privacy-policy"
        }
      ]
    });

    this.document.head.appendChild(script);
  }
}
